package com.pms.property.domain.room.dto;

public record RoomOutletTypeResponse(
    Long id,
    String propertyId,
    String roomName,
    Integer quantity,
    Boolean availableForSell,
    Integer maximumGuestOccupancy,
    String description,
    String amenitiesCsv,
    String imagesCsv
