package com.pms.property.domain.room.service;

import com.pms.property.common.exception.NotFoundException;
import com.pms.property.domain.room.dto.InventoryRoomRequest;
import com.pms.property.domain.room.dto.InventoryRoomResponse;
import com.pms.property.domain.room.dto.RoomSummaryResponse;
import com.pms.property.domain.room.repository.FloorConfigurationRepository;
import com.pms.property.domain.room.repository.FloorPropertyAreaRepository;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.PropertyAreaRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import java.util.List;
import java.util.stream.Collectors;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RoomService {

    private final FloorConfigurationRepository floorConfigurationRepository;
    private final PropertyAreaRepository propertyAreaRepository;
    private final FloorPropertyAreaRepository floorPropertyAreaRepository;
    private final RoomOutletTypeRepository roomOutletTypeRepository;
    private final InventoryRoomRepository inventoryRoomRepository;

    public RoomService(
        FloorConfigurationRepository floorConfigurationRepository,
        PropertyAreaRepository propertyAreaRepository,
        FloorPropertyAreaRepository floorPropertyAreaRepository,
        RoomOutletTypeRepository roomOutletTypeRepository,
        InventoryRoomRepository inventoryRoomRepository
    ) {
        this.floorConfigurationRepository = floorConfigurationRepository;
        this.propertyAreaRepository = propertyAreaRepository;
        this.floorPropertyAreaRepository = floorPropertyAreaRepository;
        this.roomOutletTypeRepository = roomOutletTypeRepository;
        this.inventoryRoomRepository = inventoryRoomRepository;
    }

    @Transactional(readOnly = true)
    public RoomSummaryResponse getSummaryByPropertyId(String propertyId) {
        return new RoomSummaryResponse(
            propertyId,
            floorConfigurationRepository.countByPropertyId(propertyId),
            propertyAreaRepository.countByPropertyId(propertyId),
            floorPropertyAreaRepository.countByPropertyId(propertyId),
            roomOutletTypeRepository.countByPropertyId(propertyId),
            inventoryRoomRepository.countByPropertyId(propertyId)
        );
    }

    @Transactional(readOnly = true)
    public List<InventoryRoomResponse> listInventoryRoomsByPropertyId(String propertyId) {
        return inventoryRoomRepository.findAllByPropertyId(propertyId)
            .stream()
            .map(this::toResponse)
            .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public InventoryRoomResponse getInventoryRoomById(String propertyId, Long roomId) {
        return inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .map(this::toResponse)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
    }

    @Transactional
    public InventoryRoomResponse createInventoryRoom(String propertyId, InventoryRoomRequest request) {
        InventoryRoomEntity entity = new InventoryRoomEntity();
        entity.setPropertyId(propertyId);
        entity.setFloorName(request.floorName());
        entity.setRoomTypeName(request.roomTypeName());
        entity.setRoomNumber(request.roomNumber());
        return toResponse(inventoryRoomRepository.save(entity));
    }

    @Transactional
    public InventoryRoomResponse updateInventoryRoom(String propertyId, Long roomId, InventoryRoomRequest request) {
        InventoryRoomEntity entity = inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
        entity.setFloorName(request.floorName());
        entity.setRoomTypeName(request.roomTypeName());
        entity.setRoomNumber(request.roomNumber());
        return toResponse(inventoryRoomRepository.save(entity));
    }

    @Transactional
    public void deleteInventoryRoom(String propertyId, Long roomId) {
        InventoryRoomEntity entity = inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
        inventoryRoomRepository.delete(entity);
    }

    private InventoryRoomResponse toResponse(InventoryRoomEntity entity) {
        return new InventoryRoomResponse(
            entity.getId(),
            entity.getPropertyId(),
            entity.getFloorName(),
            entity.getRoomTypeName(),
            entity.getRoomNumber()
        );
    }
}

package com.pms.property.domain.room.service;

import com.pms.property.common.exception.NotFoundException;
import com.pms.property.domain.room.dto.InventoryRoomRequest;
import com.pms.property.domain.room.dto.InventoryRoomResponse;
import com.pms.property.domain.room.dto.RoomOutletTypeResponse;
import com.pms.property.domain.room.dto.RoomSummaryResponse;
import com.pms.property.domain.room.repository.FloorConfigurationRepository;
import com.pms.property.domain.room.repository.FloorPropertyAreaRepository;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.PropertyAreaRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import java.util.List;
import java.util.stream.Collectors;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RoomService {

    private final FloorConfigurationRepository floorConfigurationRepository;
    private final PropertyAreaRepository propertyAreaRepository;
    private final FloorPropertyAreaRepository floorPropertyAreaRepository;
    private final RoomOutletTypeRepository roomOutletTypeRepository;
    private final InventoryRoomRepository inventoryRoomRepository;

    public RoomService(
        FloorConfigurationRepository floorConfigurationRepository,
        PropertyAreaRepository propertyAreaRepository,
        FloorPropertyAreaRepository floorPropertyAreaRepository,
        RoomOutletTypeRepository roomOutletTypeRepository,
        InventoryRoomRepository inventoryRoomRepository
    ) {
        this.floorConfigurationRepository = floorConfigurationRepository;
        this.propertyAreaRepository = propertyAreaRepository;
        this.floorPropertyAreaRepository = floorPropertyAreaRepository;
        this.roomOutletTypeRepository = roomOutletTypeRepository;
        this.inventoryRoomRepository = inventoryRoomRepository;
    }

    @Transactional(readOnly = true)
    public RoomSummaryResponse getSummaryByPropertyId(String propertyId) {
        return new RoomSummaryResponse(
            propertyId,
            floorConfigurationRepository.countByPropertyId(propertyId),
            propertyAreaRepository.countByPropertyId(propertyId),
            floorPropertyAreaRepository.countByPropertyId(propertyId),
            roomOutletTypeRepository.countByPropertyId(propertyId),
            inventoryRoomRepository.countByPropertyId(propertyId)
        );
    }

    @Transactional(readOnly = true)
    public List<InventoryRoomResponse> listInventoryRoomsByPropertyId(String propertyId) {
        return inventoryRoomRepository.findAllByPropertyId(propertyId)
            .stream()
            .map(this::toResponse)
            .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<RoomOutletTypeResponse> listRoomOutletTypesByPropertyId(String propertyId) {
        return roomOutletTypeRepository.findAllByPropertyId(propertyId)
            .stream()
            .map(this::toResponse)
            .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public InventoryRoomResponse getInventoryRoomById(String propertyId, Long roomId) {
        return inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .map(this::toResponse)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
    }

    @Transactional
    public InventoryRoomResponse createInventoryRoom(String propertyId, InventoryRoomRequest request) {
        InventoryRoomEntity entity = new InventoryRoomEntity();
        entity.setPropertyId(propertyId);
        entity.setFloorName(request.floorName());
        entity.setRoomTypeName(request.roomTypeName());
        entity.setRoomNumber(request.roomNumber());
        return toResponse(inventoryRoomRepository.save(entity));
    }

    @Transactional
    public InventoryRoomResponse updateInventoryRoom(String propertyId, Long roomId, InventoryRoomRequest request) {
        InventoryRoomEntity entity = inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
        entity.setFloorName(request.floorName());
        entity.setRoomTypeName(request.roomTypeName());
        entity.setRoomNumber(request.roomNumber());
        return toResponse(inventoryRoomRepository.save(entity));
    }

    @Transactional
    public void deleteInventoryRoom(String propertyId, Long roomId) {
        InventoryRoomEntity entity = inventoryRoomRepository.findByPropertyIdAndId(propertyId, roomId)
            .orElseThrow(() -> new NotFoundException("Inventory room not found: " + roomId));
        inventoryRoomRepository.delete(entity);
    }

    private InventoryRoomResponse toResponse(InventoryRoomEntity entity) {
        return new InventoryRoomResponse(
            entity.getId(),
            entity.getPropertyId(),
            entity.getFloorName(),
            entity.getRoomTypeName(),
            entity.getRoomNumber()
        );
    }

    private RoomOutletTypeResponse toResponse(RoomOutletTypeEntity entity) {
        return new RoomOutletTypeResponse(
            entity.getId(),
            entity.getPropertyId(),
            entity.getRoomName(),
            entity.getQuantity(),
            entity.getAvailableForSell(),
            entity.getMaximumGuestOccupancy(),
            entity.getDescription(),
            entity.getAmenitiesCsv(),
            entity.getImagesCsv()
        );
    }
}

package com.pms.property.domain.room.controller;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.pms.property.domain.room.dto.InventoryRoomResponse;
import com.pms.property.domain.room.dto.RoomSummaryResponse;
import com.pms.property.domain.room.service.RoomService;
import java.util.List;
import org.junit.jupiter.api.Test;

class RoomControllerTest {

    @Test
    void shouldReturnSummaryPayload() {
        RoomService service = mock(RoomService.class);
        RoomController controller = new RoomController(service);
        when(service.getSummaryByPropertyId("P-1")).thenReturn(new RoomSummaryResponse("P-1", 1, 1, 1, 1, 1));

        var response = controller.getSummary("P-1").getBody();

        assertEquals("P-1", response.data().propertyId());
    }

    @Test
    void shouldReturnInventoryRoomsPayload() {
        RoomService service = mock(RoomService.class);
        RoomController controller = new RoomController(service);
        when(service.listInventoryRoomsByPropertyId("P-1"))
            .thenReturn(List.of(new InventoryRoomResponse(1L, "P-1", "1", "Deluxe", "101")));

        var response = controller.listInventoryRooms("P-1").getBody();

        assertEquals(1, response.data().size());
    }
}

package com.pms.property.domain.room.controller;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.pms.property.domain.room.dto.InventoryRoomResponse;
import com.pms.property.domain.room.dto.RoomOutletTypeResponse;
import com.pms.property.domain.room.dto.RoomSummaryResponse;
import com.pms.property.domain.room.service.RoomService;
import java.util.List;
import org.junit.jupiter.api.Test;

class RoomControllerTest {

    @Test
    void shouldReturnSummaryPayload() {
        RoomService service = mock(RoomService.class);
        RoomController controller = new RoomController(service);
        when(service.getSummaryByPropertyId("P-1")).thenReturn(new RoomSummaryResponse("P-1", 1, 1, 1, 1, 1));

        var response = controller.getSummary("P-1").getBody();

        assertEquals("P-1", response.data().propertyId());
    }

    @Test
    void shouldReturnInventoryRoomsPayload() {
        RoomService service = mock(RoomService.class);
        RoomController controller = new RoomController(service);
        when(service.listInventoryRoomsByPropertyId("P-1"))
            .thenReturn(List.of(new InventoryRoomResponse(1L, "P-1", "1", "Deluxe", "101")));

        var response = controller.listInventoryRooms("P-1").getBody();

        assertEquals(1, response.data().size());
    }

    @Test
    void shouldReturnRoomOutletTypesPayload() {
        RoomService service = mock(RoomService.class);
        RoomController controller = new RoomController(service);
        when(service.listRoomOutletTypesByPropertyId("P-1"))
            .thenReturn(List.of(new RoomOutletTypeResponse(1L, "P-1", "Deluxe", 2, true, 2, "Desc", "A1,A2", "I1,I2")));

        var response = controller.listRoomOutletTypes("P-1").getBody();

        assertEquals(1, response.data().size());
        assertEquals("Deluxe", response.data().get(0).roomName());
    }
}

package com.pms.property.domain.room.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.pms.property.common.exception.NotFoundException;
import com.pms.property.domain.room.dto.InventoryRoomRequest;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.repository.FloorConfigurationRepository;
import com.pms.property.domain.room.repository.FloorPropertyAreaRepository;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.PropertyAreaRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class RoomServiceTest {

    @Test
    void shouldCreateInventoryRoom() {
        FloorConfigurationRepository floorConfigRepository = mock(FloorConfigurationRepository.class);
        PropertyAreaRepository propertyAreaRepository = mock(PropertyAreaRepository.class);
        FloorPropertyAreaRepository floorPropertyAreaRepository = mock(FloorPropertyAreaRepository.class);
        RoomOutletTypeRepository roomOutletTypeRepository = mock(RoomOutletTypeRepository.class);
        InventoryRoomRepository inventoryRoomRepository = mock(InventoryRoomRepository.class);
        RoomService service = new RoomService(
            floorConfigRepository,
            propertyAreaRepository,
            floorPropertyAreaRepository,
            roomOutletTypeRepository,
            inventoryRoomRepository
        );

        when(inventoryRoomRepository.save(any(InventoryRoomEntity.class))).thenAnswer(invocation -> invocation.getArgument(0));

        var response = service.createInventoryRoom("P-1", new InventoryRoomRequest("1", "Deluxe", "101"));

        assertEquals("P-1", response.propertyId());
        assertEquals("101", response.roomNumber());
    }

    @Test
    void shouldThrowWhenInventoryRoomNotFound() {
        FloorConfigurationRepository floorConfigRepository = mock(FloorConfigurationRepository.class);
        PropertyAreaRepository propertyAreaRepository = mock(PropertyAreaRepository.class);
        FloorPropertyAreaRepository floorPropertyAreaRepository = mock(FloorPropertyAreaRepository.class);
        RoomOutletTypeRepository roomOutletTypeRepository = mock(RoomOutletTypeRepository.class);
        InventoryRoomRepository inventoryRoomRepository = mock(InventoryRoomRepository.class);
        RoomService service = new RoomService(
            floorConfigRepository,
            propertyAreaRepository,
            floorPropertyAreaRepository,
            roomOutletTypeRepository,
            inventoryRoomRepository
        );

        when(inventoryRoomRepository.findByPropertyIdAndId("P-1", 33L)).thenReturn(Optional.empty());

        assertThrows(NotFoundException.class, () -> service.getInventoryRoomById("P-1", 33L));
    }
}

package com.pms.property.domain.room.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.pms.property.common.exception.NotFoundException;
import com.pms.property.domain.room.dto.InventoryRoomRequest;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.room.repository.FloorConfigurationRepository;
import com.pms.property.domain.room.repository.FloorPropertyAreaRepository;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.PropertyAreaRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class RoomServiceTest {

    @Test
    void shouldCreateInventoryRoom() {
        FloorConfigurationRepository floorConfigRepository = mock(FloorConfigurationRepository.class);
        PropertyAreaRepository propertyAreaRepository = mock(PropertyAreaRepository.class);
        FloorPropertyAreaRepository floorPropertyAreaRepository = mock(FloorPropertyAreaRepository.class);
        RoomOutletTypeRepository roomOutletTypeRepository = mock(RoomOutletTypeRepository.class);
        InventoryRoomRepository inventoryRoomRepository = mock(InventoryRoomRepository.class);
        RoomService service = new RoomService(
            floorConfigRepository,
            propertyAreaRepository,
            floorPropertyAreaRepository,
            roomOutletTypeRepository,
            inventoryRoomRepository
        );

        when(inventoryRoomRepository.save(any(InventoryRoomEntity.class))).thenAnswer(invocation -> invocation.getArgument(0));

        var response = service.createInventoryRoom("P-1", new InventoryRoomRequest("1", "Deluxe", "101"));

        assertEquals("P-1", response.propertyId());
        assertEquals("101", response.roomNumber());
    }

    @Test
    void shouldThrowWhenInventoryRoomNotFound() {
        FloorConfigurationRepository floorConfigRepository = mock(FloorConfigurationRepository.class);
        PropertyAreaRepository propertyAreaRepository = mock(PropertyAreaRepository.class);
        FloorPropertyAreaRepository floorPropertyAreaRepository = mock(FloorPropertyAreaRepository.class);
        RoomOutletTypeRepository roomOutletTypeRepository = mock(RoomOutletTypeRepository.class);
        InventoryRoomRepository inventoryRoomRepository = mock(InventoryRoomRepository.class);
        RoomService service = new RoomService(
            floorConfigRepository,
            propertyAreaRepository,
            floorPropertyAreaRepository,
            roomOutletTypeRepository,
            inventoryRoomRepository
        );

        when(inventoryRoomRepository.findByPropertyIdAndId("P-1", 33L)).thenReturn(Optional.empty());

        assertThrows(NotFoundException.class, () -> service.getInventoryRoomById("P-1", 33L));
    }

    @Test
    void shouldListRoomOutletTypesByPropertyId() {
        FloorConfigurationRepository floorConfigRepository = mock(FloorConfigurationRepository.class);
        PropertyAreaRepository propertyAreaRepository = mock(PropertyAreaRepository.class);
        FloorPropertyAreaRepository floorPropertyAreaRepository = mock(FloorPropertyAreaRepository.class);
        RoomOutletTypeRepository roomOutletTypeRepository = mock(RoomOutletTypeRepository.class);
        InventoryRoomRepository inventoryRoomRepository = mock(InventoryRoomRepository.class);
        RoomService service = new RoomService(
            floorConfigRepository,
            propertyAreaRepository,
            floorPropertyAreaRepository,
            roomOutletTypeRepository,
            inventoryRoomRepository
        );

        RoomOutletTypeEntity entity = new RoomOutletTypeEntity();
        entity.setId(8L);
        entity.setPropertyId("P-1");
        entity.setRoomName("Deluxe");
        entity.setQuantity(2);
        entity.setAvailableForSell(true);
        entity.setMaximumGuestOccupancy(2);
        entity.setDescription("Room desc");
        entity.setAmenitiesCsv("TV,WiFi");
        entity.setImagesCsv("img1,img2");

        when(roomOutletTypeRepository.findAllByPropertyId("P-1")).thenReturn(List.of(entity));

        var response = service.listRoomOutletTypesByPropertyId("P-1");

        assertEquals(1, response.size());
        assertEquals("Deluxe", response.get(0).roomName());
        assertEquals("P-1", response.get(0).propertyId());
    }
}
